@ExtendWith(MockitoExtension.class)
class SpellServiceTest {
    @Mock SpellRepository repo;
    @InjectMocks SpellService service;

    @Test
    void findsSpell() {
        when(repo.findByName("Fireball"))
            .thenReturn(Optional.of(new Spell("Fireball", 90)));
        assertTrue(service.findSpell("Fireball").isPresent());
        verify(repo).findByName("Fireball");
    }
}

